      return {
        category,
        comparable: false,
        status: "NOT_COMPARABLE",
        coverageBySoftware: Object.fromEntries(softwares.map((s) => [s.id, 0])),
        sourceAvailabilityBySoftware,
        commonCriteriaCount: 0,
        notes: "Dimens\xE3o desabilitada no escopo configurado."
      };
