      cpuModel,
      diskFreeGb,
      tempSpaceAvailableGb: diskFreeGb,
      architecture,
      operatingSystem,
      kernelRelease,
      isGvisorSandbox,
      javaAvailable,
      javaVersion,
      vmMaxMapCount,
      meetsSonarQubeLocalRequirements: blockingReasons.length === 0,
      blockingReasons,
      recommendations
