// src/workers/SonarAnalysisWorker.ts
var SonarAnalysisWorker = class {
  constructor(sonarService) {
    this.sonarService = sonarService;
  }
  static mapSonarIssueToNormalizedFinding(issue, runId = "run-sonar-worker") {
    const mappedSeverity = issue.severity === "BLOCKER" ? "BLOCKER" : issue.severity === "CRITICAL" ? "CRITICAL" : issue.severity === "MAJOR" ? "HIGH" : issue.severity === "MINOR" ? "MEDIUM" : "INFO";
    const category = issue.type === "VULNERABILITY" || issue.type === "SECURITY_HOTSPOT" ? "SAST" : "CODE_QUALITY";
    return enrichLegacyOrExternalFinding({
      id: issue.id,
      runId,
      softwareId: issue.softwareId,
      softwareName: issue.softwareName,
      softwareVersion: "1.0.0",
      toolId: issue.isExternalImportedRule ? "external-sarif" : "sonarqube-quality",
      toolName: issue.externalOriginTool || "SonarQube Server (MQR)",
      toolVersion: issue.externalOriginVersion || "26.11.0.134175",
      category,
      originalRuleId: issue.originalRuleId || issue.ruleKey,
      title: issue.ruleName,
      description: issue.message,
      severity: mappedSeverity,
      confidence: issue.confidence,
      filePath: issue.filePath,
      lineNumber: issue.lineNumber,
      snippet: issue.evidenceSnippet,
      remediation: issue.remediationGuidance,
      remediationEffortMinutes: issue.effortMinutes,
      evidenceSha256: issue.evidenceSha256,
      validationStatus: issue.hotspotReviewStatus === "REVIEWED_SAFE" ? "FALSE_POSITIVE_REVIEWED" : issue.hotspotReviewStatus === "REVIEWED_ACKNOWLEDGED" ? "ACCEPTED" : "VALIDATED"
    });
  }
  async enqueueABComparisonJob(params) {
    return this.sonarService.runStandardizedABComparison(params);
  }
};

// src/workers/ExternalReportImportWorker.ts
var ExternalReportImportWorker = class _ExternalReportImportWorker {
  static enrichExternalSarifToNormalizedFinding(params) {
    const { payload, item } = params;
    const isCodeSmellTool = payload.toolId === "eslint" || payload.toolId === "pmd" || payload.toolId === "checkstyle" || payload.toolId === "ruff";
    const category = payload.toolId === "gitleaks" ? "SECRETS" : payload.toolId === "trivy" ? "SCA" : isCodeSmellTool ? "CODE_QUALITY" : "SAST";
    return enrichLegacyOrExternalFinding({
      runId: params.runId || "run-external-sarif",
      softwareId: payload.softwareId,
      softwareName: payload.softwareName,
      softwareVersion: "1.0.0",
      toolId: payload.toolId,
      toolName: payload.toolName,
      toolVersion: payload.toolVersion,
      category,
      originalRuleId: item.ruleId,
      title: `[SARIF ${payload.toolName}] ${item.ruleId}`,
      description: item.message,
      severity: item.severity,
      confidence: item.confidence,
      filePath: item.filePath,
      lineNumber: item.lineNumber,
      snippet: item.snippet,
      remediation: `Achado importado via SARIF da ferramenta externa ${payload.toolName} (v${payload.toolVersion}). Aplicar corre\xE7\xE3o na regra ${item.ruleId}.`,
      validationStatus: "VALIDATED"
    });
  }
  static importExternalSarifFindings(params) {
    const imported = [];
    const normalizedAdded = [];
    let skipped = 0;
    for (const item of params.payload.sarifFindings) {
      const alreadyExists = params.toolsDb.sonar_issues.some(
        (si) => si.softwareId === params.payload.softwareId && si.filePath === item.filePath && si.lineNumber === item.lineNumber && si.originalRuleId === item.ruleId
      );
      if (alreadyExists) {
        skipped += 1;
        continue;
      }
      const evidenceSha256 = computeSha256(
        `EXT_SARIF|${params.payload.toolId}|${params.payload.toolVersion}|${params.payload.softwareId}|${item.filePath}:${item.lineNumber}|${item.ruleId}`
      );
      const sonarSeverity = item.severity === "BLOCKER" || item.severity === "CRITICAL" ? "BLOCKER" : item.severity === "HIGH" ? "CRITICAL" : item.severity === "MEDIUM" ? "MAJOR" : item.severity === "LOW" ? "MINOR" : "INFO";
      const enrichedNormalized = _ExternalReportImportWorker.enrichExternalSarifToNormalizedFinding({
        payload: params.payload,
        item,
        runId: params.analysisId
      });
      const issueRec = {
        id: `sext-${evidenceSha256.slice(0, 12)}`,
        issueKey: `ext-${params.payload.toolId}-${evidenceSha256.slice(0, 8)}`,
        analysisId: params.analysisId,
        projectKey: params.payload.projectKey,
        softwareId: params.payload.softwareId,
        softwareName: params.payload.softwareName,
        type: params.payload.toolId === "eslint" || params.payload.toolId === "pmd" || params.payload.toolId === "checkstyle" || params.payload.toolId === "ruff" ? "CODE_SMELL" : "VULNERABILITY",
        severity: sonarSeverity,
        ruleKey: `external_${params.payload.toolId}:${item.ruleId}`,
        ruleName: `[Externo Importado via SARIF: ${params.payload.toolName} v${params.payload.toolVersion}] ${item.ruleId}`,
        isExternalImportedRule: true,
        externalOriginTool: params.payload.toolName,
        externalOriginVersion: params.payload.toolVersion,
        originalRuleId: item.ruleId,
        confidence: item.confidence,
        filePath: item.filePath,
        lineNumber: item.lineNumber,
        message: item.message,
        effortMinutes: enrichedNormalized.remediationEffortMinutes,
        remediationGuidance: `Achado importado via SARIF da ferramenta externa ${params.payload.toolName} (v${params.payload.toolVersion}). N\xE3o pertence ao Quality Profile nativo do SonarQube.`,
        evidenceSnippet: item.snippet,
        evidenceSha256
      };
      imported.push(issueRec);
      normalizedAdded.push(enrichedNormalized);
      params.toolsDb.sonar_issues.unshift(issueRec);
      params.existingNormalizedFindings.push(enrichedNormalized);
    }
    const toolCatalogEntry = params.toolsDb.sonar_integrations.externalToolsSupported.find(
      (t) => t.toolId === params.payload.toolId
    );
    if (toolCatalogEntry) {
      toolCatalogEntry.importedIssuesCount += imported.length;
    }
    return {
      importedToSonarIssues: imported,
      normalizedFindingsAdded: normalizedAdded,
      deduplicatedSkippedCount: skipped,
      message: `${imported.length} achado(s) SARIF de ${params.payload.toolName} v${params.payload.toolVersion} importados com origem e impactos MQR preservados (${skipped} duplicado(s) ignorado(s)).`
    };
  }
};

